[meta]
name = The Cemetery of Ashes
ambient = 0.34 0.33 0.37
fog = 0.30 0.30 0.34
fog_range = 8 34
sky = overcast
torch = 5 0.6 0.55 0.5
start = 10 45 -90
default = ,
edge_top = 7
entity_floor = auto

// Where the Ashen wake. A walled hollow of graves among the cliffs, under a grey dusk; you climb out
// of an open grave as the town's bell tolls somewhere beyond. A lane leads north between the walls
// to a field of headstones where the husks of the Ashen who woke before you still wander; up the
// steps, a dark chapel with its far door sealed in silk; past it a shrine in a small court, and
// the great door of the Sexton, who keeps the cemetery's gate. Beyond the gate, Harrowmere.
// The way runs one way only: once through the gate there is no coming back.

[legend]
# = wall tex=ash_rock top=7 cap=ash_ground
v = wall tex=ash_stone top=9 cap=ash_ground
w = wall tex=ash_brick top=3.6 cap=ash_ground
k = wall tex=ash_brick top=6 cap=ash_ground
, = floor tex=ash_grass h=0
. = floor tex=ash_ground h=0
1 = floor tex=ash_ground h=0.4 side=ash_stone
c = floor tex=ash_flagstone h=0.8 ceil=4.6 ceil_tex=ash_brick side=ash_brick dark=0.25
f = floor tex=flagstone h=0.8 side=ash_stone
a = floor tex=ash_flagstone h=0.8 side=ash_stone
g = floor tex=ash_ground h=0.8 side=ash_stone

