[entities]
// The waking hollow: the open grave you climb out of, rows of headstones, the first shrine.
M = hint text="{W A S D} walk. The {mouse} looks about.|Climb out of the grave and follow the path north."
O = open_grave
S = save_statue
Á = hint text="A shrine. Press {E} beside it to pray:|it mends you and records your journey."
G = gravestone
Y = tree kind=cypress
R = urn
L = torch radius=6
// The lane between the walls, and the Rusted Sword left against one of them.
Â = hint text="Something lies against the wall ahead.|Press {E} to open a chest."
C = chest item=rusted_sword
Ã = hint text="Open {Belongings} with {Tab}, choose a weapon and press {1}|to hold it as your {Primary}."
// The field of headstones, where the husks of those who failed still wander.
Ä = hint text="{Left mouse} swings your Primary. Hold it for a heavy blow."
Å = hint text="Every blow and every sprint ({Shift}) spends stamina.|Step back and let it refill."
Ì = hint text="Urns break when struck, and spill what they hold.|The {wheel} picks a quick item; {middle mouse} uses it."
B = bone_walker model=grave
A = ashen_husk
X = mourner
Z = brazier radius=8
Æ = hint text="Ash lies thick on the chapel steps.|Many of the Ashen came this way. None came back." on=1
// The chapel: the Flame Bolt's scroll by its west wall, a cold brazier, and its far door sealed in silk.
Ç = hint text="Silk seals the chapel's far door. No blade will cut it."
D = chest item=scroll_flame gold=15 model=worn
È = hint text="A scroll: choose it in {Belongings} to learn its spell,|then press {2} on the spell to ready it as your {Secondary}."
É = hint text="{Right mouse} casts your Secondary's spell.|Burn the silk."
W = secret_wall model=web on=c
U = brazier unlit radius=7
P = pillar
Q = sarcophagus
V = candles
K = cobweb
N = skull_niche
// The shrine court before the great door.
T = save_statue
Ê = hint text="A great door, and something waiting behind it.|Pray at the shrine first, then press {E} at the door."
// The Sexton's yard, and the cemetery's gate out to Harrowmere, shut until its keeper falls.
F = door boss=sexton_dead on=a
J = sexton
// Its yard: stone mourners bowed either side of the gate, crypts set in the walls, fenced family
// plots, fresh graves, and heaps of the ash it shovels from its pyres. Dead trees in the corners.
Ö = mourning_statue
Ô = crypt_front
Õ = grave_railing
Ø = ash_mound
Ú = bones
Ð = tree kind=dead
E = exit map=harrowmere at=2,31,0 label=Leave_the_cemetery model=cemetery_gate yaw=90 oneway requires=sexton_dead shut="The gate will not yield while its keeper stands."
// A cold grey light falling on the gate, so its stone shows against the dark beyond it.
Ó = light y=4.5 color=0.5,0.52,0.62 radius=7
